module Parallel {
  use BlockDist;
  use Time;
  use IO;
  use JSON;
  use Sockets;

  config const size: int = 16384;
  config const time_dim: int = 1024;
  config const numLocales: int = here.maxTaskPar;
  config const maxTasksPerLocale: int = here.maxTaskPar;
  config const port: int = 8080;
  config const logLevel: int = 1; 

  const Space = {0..size-1} dmapped Block(boundingBox={0..size-1});
  const logFilePath = "execution.log";

  proc logMessage(level: int, message: string) {
    if level <= logLevel {
      try {
        var logFile = open(logFilePath, iomode.a);
        var logWriter = logFile.writer();
        var now = Time.getCurrentTime();
        logWriter.writef("%s: %s\n", now, message);
        logWriter.close();
        logFile.close();
      } catch e: Error {
        writeln("Fatal Log Error: ", e.message());
      }
    }
  }

  proc b_spline_basis(x: real, degree: int, knots: [] real, out basis: [] real) throws {
    const n = knots.size - 1;
    if degree < 0 || degree > n {
      throw new owned Error("Degree must be non-negative and less than or equal to the number of knots.");
    }

    var my_basis: [0..n-1] real = 0.0;

    var span = -1;
    for i in 0..n-1 {
      if x >= knots[i] && x < knots[i+1] {
        span = i;
        break;
      }
    }
    if x == knots[n] {
      span = n - degree - 1;
    }
    if span == -1 {
      basis = my_basis;
      return;
    }

    var temp: [0..degree] real = 0.0;
    my_basis[span-degree] = 1.0;

    for k in 1..degree {
      var saved: real = 0.0;
      for j in 0..k-1 {
        var i = span - k + j;
        var den1 = knots[i+k] - knots[i];
        var den2 = knots[i+k+1] - knots[i+1];
        var term1 = if den1 != 0.0 then ((x - knots[i]) / den1) * my_basis[i] else 0.0;
        var term2 = if den2 != 0.0 then ((knots[i+k+1] - x) / den2) * my_basis[i+1] else 0.0;
        temp[j] = saved + term1;
        saved = term2;
      }
      temp[k] = saved;
      for j in 0..k {
        my_basis[span-k+j] = temp[j];
      }
    }

    basis = my_basis;
  }

  proc kan_spline_eval(x: real, coeffs: [] real, grid: int, degree: int): real throws {
    const num_knots = grid + degree + 1;
    var knots: [0..num_knots-1] real;
    for i in 0..num_knots-1 {
      knots[i] = i:real / (num_knots-1):real;
    }

    var basis_values: [0..grid] real;
    try {
      b_spline_basis(x, degree, knots, basis_values);
    } catch e {
      throw new owned Error("B-spline basis calculation failed: " + e.message());
    }

    var sum: real = 0.0;
    const num_coeffs = coeffs.size;
    for i in 0..grid {
      if i < num_coeffs {
        sum += basis_values[i] * coeffs[i];
      }
    }
    return sum;
  }

  proc kan_tgn_update(nodes: [Space] real, memory: [Space] real, time_factor: real, grid: int, degree: int): [Space] real throws {
    var updated: [Space] real;

    if grid <= 0 {
      throw new owned Error("Invalid grid size: must be positive.");
    }
    if time_factor < 0.0 || time_factor > 1.0 {
      throw new owned Error("Invalid time factor: must be between 0.0 and 1.0.");
    }

    coforall loc in Locales do on loc {
      var localDomain = nodes.localSubdomain();
      if localDomain.size == 0 {
        continue;
      }

      var numTasks = min(maxTasksPerLocale, localDomain.size);
      var chunkSize = (localDomain.size + numTasks - 1) / numTasks;

      coforall tid in 0..numTasks-1 {
        var start = localDomain.low + tid * chunkSize;
        var end = min(localDomain.high, start + chunkSize - 1);

        if start > end {
          continue;
        }

        try {
          var coeffs: [0..grid] real = 1.0;
          for i in start..end {
            var spline_x = i: real / (size-1): real;
            var spline_val = kan_spline_eval(spline_x, coeffs, grid, degree);
            updated[i] = memory[i] * (1.0 - time_factor) + nodes[i] * time_factor + spline_val * 0.01;
          }
        } catch e {
          logMessage(1, "Error in parallel task " + tid:string + " on locale " + loc.id:string + ": " + e.message());
          throw e;
        }
      }
    }
    return updated;
  }

  proc parseAndDistribute(jsonArray: borrowed JsonArray, ref distArray: [Space] real) throws {
    if jsonArray.size() != size {
      throw new owned Error("Input array size mismatch. Expected " + size:string + ", got " + jsonArray.size():string);
    }
    var localTemp: [0..size-1] real;
    for (i, val) in zip(0..size-1, jsonArray.toArray()) {
      if val.isReal() {
        localTemp[i] = val.toReal();
      } else if val.isInt() {
        localTemp[i] = val.toInt():real;
      } else {
        throw new owned Error("Invalid numeric type in input array at index " + i:string);
      }
    }
    forall (da, lt) in zip(distArray, localTemp) {
      da = lt;
    }
  }

  proc handleRequest(channel: channel(true, string, true)) throws {
    var request_str = channel.read();
    var jsonReq: JsonValue;
    var response: string;

    try {
      jsonReq = parseJson(request_str);
    } catch e {
      response = "{\"error\":\"Invalid JSON format: " + e.message() + "\"}";
      channel.write(response);
      return;
    }

    var nodes: [Space] real;
    var memory: [Space] real;
    var time_factor: real;
    var grid: int;
    var degree: int;

    try {
      if !jsonReq.isObject() { 
        throw new owned Error("Request must be a JSON object."); 
      }
      var reqObj = jsonReq.toObject();
      if !reqObj.has("nodes") || !reqObj.has("memory") || !reqObj.has("time_factor") || !reqObj.has("grid") || !reqObj.has("degree") {
        throw new owned Error("Missing required parameters: nodes, memory, time_factor, grid, degree.");
      }

      parseAndDistribute(reqObj.get("nodes").toArray(), nodes);
      parseAndDistribute(reqObj.get("memory").toArray(), memory);
      time_factor = reqObj.get("time_factor").toReal();
      grid = reqObj.get("grid").toInt();
      degree = reqObj.get("degree").toInt();

    } catch e {
      response = "{\"error\":\"Invalid input parameters: " + e.message() + "\"}";
      channel.write(response);
      return;
    }

    var timer: stopwatch;
    timer.start();
    try {
      var result = kan_tgn_update(nodes, memory, time_factor, grid, degree);
      var localResult: [0..size-1] real;
      forall (lr, dr) in zip(localResult, result) {
        lr = dr;
      }
      var resJson = new owned JsonObject();
      resJson.set("result", new owned JsonArray(localResult));
      response = resJson.toString();

    } catch e {
      response = "{\"error\":\"Computation failed: " + e.message() + "\"}";
    }
    timer.stop();
    logMessage(2, "Request processed in " + timer.elapsed():string + " seconds.");
    channel.write(response);
  }

  proc main() {
    logMessage(1, "Server starting on port " + port:string);
    try {
      var listener = listen(port);
      writeln("Server listening on port ", port);

      while true {
        var conn = listener.accept();
        var comm_channel = new owned channel(true, string, true, conn);
        try {
          handleRequest(comm_channel);
        } catch e {
          logMessage(1, "Error handling request: " + e.message());
          try {
            comm_channel.write("{\"error\":\"Internal server error.\"}");
          } catch io_e {
            logMessage(1, "Failed to send error response: " + io_e.message());
          }
        } finally {
          comm_channel.close();
          conn.close();
        }
      }
    } catch e: Error {
      logMessage(0, "Fatal server error: " + e.message());
      writeln("Fatal server error: Could not start listener on port ", port, ". ", e.message());
    }
  }
}

