module Parallel {
  use BlockDist;
  use Time;
  use IO;
  use JSON;
  use Sockets;

  config const size: int = 16384;
  config const time_dim: int = 1024;
  config const numLocales: int = here.maxTaskPar; 
  config const maxTasksPerLocale: int = 4;
  config const port: int = 8080;
  config const logLevel: int = 1;

  const Space: domain(1) = {0..#size} dmapped Block(boundingBox={0..#size-1});
  const logFilePath = "execution.log";

  proc logMessage(level: int, message: string) {
    if level <= logLevel {
      try {
        var logFile = open(logFilePath, iomode.a);
        var logWriter = logFile.writer();
        var now = getCurrentTime();
        logWriter.writef("%s: %s\n", now:string, message);
        logWriter.close();
      } catch e: AnyException {
        writeln("Fatal Log Error: ", e:string);
      }
    }
  }

  proc b_spline_basis(x: real, degree: int, knots: [] real, out basis: [] real) throws {
    const m = knots.size;
    if degree < 0 || degree >= m {
      throw new Error("Degree must be non-negative and less than the number of knots.");
    }
    const nBasis = m - degree - 1;
    basis = new real[nBasis];
    for i in 0..#nBasis do basis[i] = 0.0;

    if nBasis <= 0 {
      return;
    }

    var iSpan = -1;
    for i in 0..#(m-1) {
      if i + 1 < m && x >= knots[i] && x < knots[i+1] {
        iSpan = i;
        break;
      }
    }
    if x >= knots[m-1] {
      iSpan = m - 2;
    }
    if iSpan < 0 {
      return;
    }

    var ndu = new real[degree+1, degree+1];
    ndu[0,0] = 1.0;
    var left = new real[degree+1];
    var right = new real[degree+1];

    for j in 1..degree {
      left[j] = x - knots[iSpan+1-j];
      right[j] = knots[iSpan+j] - x;
      var saved = 0.0;
      for r in 0..j-1 {
        var denom = right[r+1] + left[j-r];
        var temp = if denom.abs > 0.0 then ndu[r,j-1] / denom else 0.0;
        ndu[r,j] = right[r+1] * temp;
        var val = left[j-r] * temp;
        ndu[j,r] = val;
        saved = saved + ndu[r,j];
      }
      ndu[j,j] = 1.0 - saved;
    }

    for j in 0..degree {
      basis[iSpan-degree+j+1] = ndu[j,degree];
    }

    var ders = new real[degree+1, degree+1];
    for r in 0..degree do ders[0,r] = ndu[r,degree];
    var a = new real[2,degree+1];
    for r in 0..degree {
      var s1 = 0;
      var s2 = 1;
      a[0,r] = 1.0;
      for k in 1..degree {
        var d = 0.0;
        var rk = r - k;
        var pk = degree - k;
        if r >= k {
          a[s2,0] = a[s1,0] / (knots[r+1] - knots[r-k+1]);
          d = a[s2,0] * (knots[r+1] - x);
        }
        var j1 = if rk >= -1 then 1 else -rk;
        var j2 = if r-1 <= pk then k-1 else degree - r;
        for j in j1..j2 {
          a[s2,j] = (a[s1,j] - a[s1,j-1]) / (knots[r+j+1] - knots[r+j-k+1]);
          d += a[s2,j] * (knots[r+j+1] - x);
        }
        if r <= pk {
          a[s2,k] = -a[s1,k-1] / (knots[r+k+1] - knots[r+1]);
          d += a[s2,k] * (knots[r+k+1] - x);
        }
        ders[k,r] = d;
        var tmp = s1; s1 = s2; s2 = tmp;
      }
    }
  }

  proc kan_spline_eval(x: real, coeffs: [] real, grid: int, degree: int): real throws {
    if grid <= 0 {
      throw new Error("Grid must be positive.");
    }
    const num_knots = grid + degree + 1;
    var knots = new real[num_knots];
    for i in 0..#num_knots do knots[i] = i:real / (num_knots-1):real;

    const nBasis = num_knots - degree - 1;
    var basis = new real[nBasis];
    for i in 0..#nBasis do basis[i] = 0.0;

    try {
      b_spline_basis(x, degree, knots, basis);
    } catch e {
      throw new Error("B-spline basis calculation failed: " + e:string);
    }

    var sum: real = 0.0;
    const num_coeffs = coeffs.size;
    for i in 0..#nBasis {
      if i < num_coeffs {
        sum += basis[i] * coeffs[i];
      }
    }
    return sum;
  }

  proc kan_tgn_update(nodes: [Space] real, memory: [Space] real, time_factor: real, grid: int, degree: int): [Space] real throws {
    if grid <= 0 {
      throw new Error("Invalid grid size: must be positive.");
    }
    if time_factor < 0.0 || time_factor > 1.0 {
      throw new Error("Invalid time factor: must be between 0.0 and 1.0.");
    }

    var updated: [Space] real = 0.0;

    for loc in Locales do on loc {
      var localDomain = nodes.localSubdomain();
      if localDomain.size == 0 {
        continue;
      }

      var numTasks = min(maxTasksPerLocale, localDomain.size);
      var chunkSize = (localDomain.size + numTasks - 1) / numTasks;

      coforall tid in 0..numTasks-1 with (ref updated, ref nodes, ref memory) {
        var start = localDomain.low + tid * chunkSize;
        var end = min(localDomain.high, start + chunkSize - 1);
        if start > end then continue;

        var coeffs = new real[grid+1];
        for i in 0..#(grid+1) do coeffs[i] = 1.0;

        for i in start..end {
          var spline_x = i:real / size:real;
          var spline_val: real;
          try {
            spline_val = kan_spline_eval(spline_x, coeffs, grid, degree);
          } catch e {
            logMessage(1, "Spline eval error on locale " + loc.id:string + " tid " + tid:string + ": " + e:string);
            throw e;
          }
          updated[i] = memory[i] * (1.0 - time_factor) + nodes[i] * time_factor + spline_val * 0.01;
        }
      }
    }

    return updated;
  }

  proc parseAndDistribute(jsonArray: borrowed JsonArray, ref distArray: [Space] real) throws {
    if jsonArray.size() != size {
      throw new Error("Input array size mismatch. Expected " + size:string + ", got " + jsonArray.size():string);
    }

    var temp = new real[size];
    for i in 0..#size do
      temp[i] = 0.0;

    var idx = 0;
    for val in jsonArray {
      if val.isReal() then
        temp[idx] = val.toReal();
      else if val.isInt() then
        temp[idx] = val.toInt():real;
      else
        throw new Error("Invalid numeric type in input array at index " + idx:string);
      idx += 1;
    }

    forall (i in Space) {
      distArray[i] = temp[i];
    }
  }

  proc handleRequest(sock: Socket) throws {
    var buf = "";
    try {
      var reader = sock.reader();
      var line = reader.readLine();
      if line == nil {
        var writer = sock.writer();
        writer.write("{\"error\":\"Empty request\"}\n");
        writer.flush();
        return;
      }
      buf = line;
      while reader.available() > 0 {
        var more = reader.readLine();
        if more == nil then break;
        buf += more;
      }
    } catch e {
      try {
        var w = sock.writer();
        w.write("{\"error\":\"Failed to read request: " + e:string + "\"}\n");
        w.flush();
      } catch { }
      return;
    }

    var jsonReq: JsonValue;
    var response: string;
    try {
