        logWriter.close();
        logFile.close();
      } catch e: Error {
        writeln("Fatal Log Error: ", e.message());
      }
    }
  }

  proc b_spline_basis(x: real, degree: int, knots: [] real, out basis: [] real) throws {
    const n = knots.size - 1;
    if degree < 0 || degree > n {
      throw new owned Error("Degree must be non-negative and less than or equal to the number of knots.");
    }

    var my_basis: [0..n-1] real = 0.0;

    var span = -1;
    for i in 0..n-1 {
      if x >= knots[i] && x < knots[i+1] {
        span = i;
        break;
      }
    }
    if x == knots[n] {
      span = n - degree - 1;
    }
    if span == -1 {
      basis = my_basis;
      return;
    }

    var temp: [0..degree] real = 0.0;
    my_basis[span-degree] = 1.0;

    for k in 1..degree {
      var saved: real = 0.0;
      for j in 0..k-1 {
        var i = span - k + j;
        var den1 = knots[i+k] - knots[i];
        var den2 = knots[i+k+1] - knots[i+1];
        var term1 = if den1 != 0.0 then ((x - knots[i]) / den1) * my_basis[i] else 0.0;
        var term2 = if den2 != 0.0 then ((knots[i+k+1] - x) / den2) * my_basis[i+1] else 0.0;
        temp[j] = saved + term1;
        saved = term2;
      }
      temp[k] = saved;
      for j in 0..k {
        my_basis[span-k+j] = temp[j];
      }
    }

    basis = my_basis;
  }

  proc kan_spline_eval(x: real, coeffs: [] real, grid: int, degree: int): real throws {
    const num_knots = grid + degree + 1;
    var knots: [0..num_knots-1] real;
    for i in 0..num_knots-1 {
      knots[i] = i:real / (num_knots-1):real;
    }

    var basis_values: [0..grid] real;
    try {
      b_spline_basis(x, degree, knots, basis_values);
    } catch e {
      throw new owned Error("B-spline basis calculation failed: " + e.message());
    }

    var sum: real = 0.0;
    const num_coeffs = coeffs.size;
    for i in 0..grid {
      if i < num_coeffs {
        sum += basis_values[i] * coeffs[i];
      }
    }
    return sum;
  }

  proc kan_tgn_update(nodes: [Space] real, memory: [Space] real, time_factor: real, grid: int, degree: int): [Space] real throws {
    var updated: [Space] real;

