          var coeffs: [0..grid] real = 1.0;
          for i in start..end {
            var spline_x = i: real / (size-1): real;
            var spline_val = kan_spline_eval(spline_x, coeffs, grid, degree);
            updated[i] = memory[i] * (1.0 - time_factor) + nodes[i] * time_factor + spline_val * 0.01;
          }
        } catch e {
