          throw e;
        }
      }
    }
    return updated;
  }

  proc parseAndDistribute(jsonArray: borrowed JsonArray, ref distArray: [Space] real) throws {
    if jsonArray.size() != size {
      throw new owned Error("Input array size mismatch. Expected " + size:string + ", got " + jsonArray.size():string);
    }
    var localTemp: [0..size-1] real;
    for (i, val) in zip(0..size-1, jsonArray.toArray()) {
      if val.isReal() {
        localTemp[i] = val.toReal();
      } else if val.isInt() {
        localTemp[i] = val.toInt():real;
      } else {
