        logWriter.writef("%s: %s\n", now, message);
        logWriter.close();
      } catch e: SystemError {
        writeln("Fatal Log Error: ", e.message());
      }
    }
  }

  proc b_spline_basis(x: real, degree: int, knots: [] real, out basis: [] real) throws {
    const n = knots.size - 1;
    if degree < 0 || degree > n {
      throw new Error("Degree must be non-negative and less than the number of knots.");
    }

    var my_basis: [0..n-1] real = 0.0;

    var span = -1;
    for i in degree..n-degree {
      if x >= knots[i] && x < knots[i+1] {
        span = i;
        break;
      }
    }
    if x == knots[n-degree] {
      span = n - degree - 1;
    }
    if span == -1 {
      basis = my_basis;
      return;
    }

    var temp: [0..degree] real = 0.0;
    my_basis[span] = 1.0;

    for k in 1..degree {
      var saved: real = 0.0;
      for j in 0..k-1 {
        var i = span - k + j;
        var den1 = knots[i+k] - knots[i];
        var den2 = knots[i+k+1] - knots[i+1];
        var term1 = if den1 > 0.0 then (x - knots[i]) / den1 * my_basis[i] else 0.0;
        var term2 = if den2 > 0.0 then (knots[i+k+1] - x) / den2 * my_basis[i+1] else 0.0;
        my_basis[i] = saved + term2;
        saved = term1;
      }
      my_basis[span] = saved;
    }

    basis = my_basis;
  }

