      buf = line;
      while reader.available() > 0 {
        var more = reader.readLine();
        if more == nil then break;
        buf += more;
      }
    } catch e {
      logMessage(1, "Failed to read request: " + (e:string));
      throw e;
    }

    var request_str = buf;
    var jsonReq: JsonValue;
    var response: string;

    try {
      jsonReq = parseJson(request_str);
    } catch e {
      response = "{\"error\":\"Invalid JSON format: " + e.message() + "\"}";
      var w = sock.writer();
