      time_factor = reqObj.get("time_factor").toReal();
      grid = reqObj.get("grid").toInt();
      degree = reqObj.get("degree").toInt();

    } catch e {
      response = "{\"error\":\"Invalid input parameters: " + e.message() + "\"}";
      var w = sock.writer();
      w.write(response + "\n");
      w.flush();
      return;
    }

    var timer = new Timer();
    timer.start();
    try {
      var result = kan_tgn_update(nodes, memory, time_factor, grid, degree);
      var localResult: [0..size-1] real;
      forall (lr, dr) in zip(localResult, result) {
        lr = dr;
      }
      var resJson = new owned JsonObject();
      resJson.set("result", new owned JsonArray(localResult));
      response = resJson.toString();

    } catch e {
      response = "{\"error\":\"Computation failed: " + e.message() + "\"}";
    }
    timer.stop();
    logMessage(2, "Request processed in " + timer.elapsed():string + " seconds.");
    try {
      var w = sock.writer();
      w.write(response + "\n");
      w.flush();
    } catch e {
      logMessage(1, "Failed to send response: " + e.message());
    }
  }

  proc main() {
    logMessage(1, "Server starting on port " + port:string);
    try {
      var listener = new ServerSocket(port);
      listener.listen();
      writeln("Server listening on port ", port);
      while true {
        var conn = listener.accept();
        if conn == nil then continue;
        spawn {
          try {
            handleRequest(conn);
          } catch e {
            logMessage(1, "Error handling request: " + (e:string));
            try {
