            } catch { }
          } finally {
            conn.close();
          }
        }
      }
    } catch e: AnyException {
      logMessage(0, "Fatal server error: " + (e:string));
      writeln("Fatal server error: Could not start listener on port ", port, ". ", (e:string));
    }
  }
