  proc b_spline_basis(x: real, degree: int, knots: [] real, out basis: [] real) throws {
    const n = knots.size - 1;
    if degree < 0 || degree > n {
      throw new owned Error("Degree must be non-negative and less than or equal to the number of knots.");
    }

    var my_basis: [0..n-1] real = 0.0;

    var span = -1;
    for i in 0..n-1 {
      if x >= knots[i] && x < knots[i+1] {
        span = i;
        break;
      }
    }
    if x == knots[n] {
      span = n - degree - 1;
    }

    if span < degree {
      basis = my_basis;
      return;
    }

    var temp: [0..degree] real = 0.0;
    my_basis[span-degree] = 1.0;

    for k in 1..degree {
      var saved: real = 0.0;
